M.update({  # NAP-093: first steps for authors, explanations of audio terms, empty states that say what to do
"terms.what_is": ("Что такое «{term}»?", "What is “{term}”?"),
"terms.close": ("Закрыть пояснение", "Close explanation"),
"terms.carrier.name": ("Несущая", "Carrier"),
"terms.carrier.text": ("Основной тон генератора, который слышен в наушниках. Для бинаурального ритма в левый и правый канал подаются две несущие с небольшой разницей частот.",
  "The generator’s main tone, the one you hear in the headphones. For a binaural beat the left and right channels get two carriers with a small difference in frequency."),
"terms.beat.name": ("Бинауральный ритм", "Binaural beat"),
"terms.beat.text": ("Разница частот левой и правой несущей: например, 205 и 195 Гц дают ритм 10 Гц. Звука с частотой ритма в файле нет, его воспринимает мозг, поэтому слушать нужно в наушниках.",
  "The difference between the left and right carrier frequencies: for example, 205 and 195 Hz give a 10 Hz beat. The file contains no sound at the beat frequency; the brain perceives it, so it has to be heard on headphones."),
"terms.separation.name": ("Подавление противоположной несущей", "Opposite carrier suppression"),
"terms.separation.text": ("Насколько слабее в канале чужая несущая, чем своя: левая в правом канале и правая в левом. Чем больше дБ, тем чище разделение: для бинаурального ритма каждое ухо должно слышать только свою несущую.",
  "How much weaker the other channel’s carrier is than the channel’s own: the left carrier in the right channel and vice versa. More dB means cleaner separation; for a binaural beat each ear should hear only its own carrier."),
"terms.lufs.name": ("LUFS", "LUFS"),
"terms.lufs.text": ("Единица воспринимаемой громкости (ITU-R BS.1770, EBU R128). Интегральная громкость — среднее за весь трек: −16 LUFS громче, чем −23 LUFS. Конвертер измеряет её до и после; громкость меняется, только если пришлось понизить уровень из-за пика.",
  "A unit of perceived loudness (ITU-R BS.1770, EBU R128). Integrated loudness is the average over the whole track: −16 LUFS is louder than −23 LUFS. The converter measures it before and after; loudness changes only if the level had to be lowered because of a peak."),
"terms.true_peak.name": ("True peak", "True peak"),
"terms.true_peak.text": ("Пиковый уровень сигнала (в dBTP) с учётом значений между отсчётами, которые возникают при воспроизведении. Выше 0 dBTP звук на некоторых устройствах искажается, поэтому пик держится ниже потолка.",
  "The signal’s peak level (in dBTP), including the values between samples that appear on playback. Above 0 dBTP some devices distort the sound, so the peak is kept below the ceiling."),
"terms.gain.name": ("Общее усиление", "Common gain"),
"terms.gain.text": ("На сколько дБ конвертер изменил уровень всего трека, чтобы пик не превысил потолок. 0 дБ — уровень не менялся. Все каналы меняются одинаково, поэтому баланс и ритм сохраняются.",
  "How many dB the converter changed the level of the whole track so the peak stays under the ceiling. 0 dB means the level was not changed. All channels change by the same amount, so the balance and the beat are kept."),
"terms.dbfs.name": ("dBFS", "dBFS"),
"terms.dbfs.text": ("Уровень относительно максимума цифрового сигнала: 0 dBFS — самый громкий возможный отсчёт, −20 dBFS — в 10 раз меньше по амплитуде.",
  "Level relative to the digital maximum: 0 dBFS is the loudest possible sample, −20 dBFS is ten times smaller in amplitude."),
"terms.ramp.name": ("Плавный вход", "Ramp"),
"terms.ramp.text": ("Время, за которое генератор плавно нарастает от тишины до заданной громкости в начале клипа и так же затихает в конце, без щелчков.",
  "How long the generator takes to rise smoothly from silence to the set level at the start of the clip and to fade the same way at the end, without clicks."),
"first.title": ("С чего начать", "Where to start"),
"first.lead": ("Путь от звукового файла до приложения в магазине. Каждый шаг можно сохранить и вернуться к нему позже.",
  "The way from an audio file to an app in the store. Every step can be saved and picked up later."),
"first.create": ("Создайте черновик: адрес, автор, категория и название.", "Create a draft: address, author, category and title."),
"first.audio": ("На вкладке «Звук» выберите профиль и загрузите файл. Конвертация запустится сама.", "On the Audio tab pick a profile and upload a file. The conversion starts by itself."),
"first.qa": ("Проверьте отчёт качества: прослушайте результат, посмотрите несущие, громкость и true peak.", "Check the quality report: listen to the result, look at the carriers, loudness and true peak."),
"first.program": ("На вкладке «Программа» соберите сеансы из готовых треков.", "On the Program tab build sessions from the finished tracks."),
"first.submit": ("Подтвердите права, укажите цену и отправьте версию на модерацию. После одобрения вы опубликуете её сами или автоматически.",
  "Confirm the rights, set a price and send the version to moderation. Once approved, you publish it yourself or automatically."),
"first.start": ("Создать первый черновик", "Create the first draft"),
"dev.no_sales": ("Продаж пока нет. Они появятся здесь после первой оплаты опубликованного приложения.", "No sales yet. They appear here after the first payment for a published app."),
"dev.go_apps": ("К приложениям", "Go to apps"),
"account.no_devices": ("Устройств пока нет. Устройство добавляется в проигрывателе перед первым сеансом.", "No devices yet. A device is added in the player before the first session."),
"account.no_history": ("Сеансов пока не было. Откройте приложение из библиотеки и начните сеанс.", "No sessions yet. Open an app from your library and start a session."),
"account.to_library": ("Открыть библиотеку", "Open library"),
})

