def nest(lang):
    out = {}
    for key, pair in M.items():
        cur = out
        parts = key.split(".")
        for p in parts[:-1]: cur = cur.setdefault(p, {})
        cur[parts[-1]] = pair[0 if lang == "ru" else 1]
    return out

d = pathlib.Path(__file__).resolve().parent.parent / "messages"
d.mkdir(exist_ok=True)
for lang in ("ru", "en"):
    (d / f"{lang}.json").write_text(json.dumps(nest(lang), ensure_ascii=False, indent=1) + "\n", encoding="utf-8")
print(len(M), "keys")
